#!/bin/bash
# setup-all-in-one.sh - set up minimal templating plus any of the modules in this repository,
# from scratch or as an update.
# GENERATED by tools/build.py from the plain files beside it: edit those, then rebuild.
# Run in dom0 as your normal user (not root/sudo). Safe to re-run.
# All questions are asked first; after that it runs without stopping.
#
# Which templates and qubes get built is set in
# ~/.config/minimal-templating/templates.conf: its header explains every option.
#
#  0. Questions: one per module (listed below), then: OK to shut down ALL qubes later?
#       sys-net-wifi: sys-net Wi-Fi persistence
#       sys-vpn-wireguard: sys-vpn WireGuard autoconnect
#       flatpak: Flatpak integration
#  1. Stops the watcher while setting up (it is enabled again at the end).
#  2. dom0: installs minimal-templating, minimal-templating-listen and the systemd
#     user unit (overwriting older copies). templates.conf is only written if
#     missing; the default always goes to templates.conf.example.
#  3. Base template (from templates.conf, default fedora-44-minimal): downloads it
#     if missing, runs dnf upgrade, installs master.dnf, writes
#     /etc/minimal-templating/apply and the lists (overwriting these; other lists
#     you added are kept), and does each chosen module's part in the base
#     (packages, lists, templates.conf sections),
#     then shuts it down and waits until its disk is saved.
#  4. Builds every derived template and disposable template (offline, so all
#     qubes keep running). Stops here if any build fails.
#  5. Creates /rw/config/rc.local.d and rc.local-early.d in every disposable
#     template and runs the chosen modules that go into one.
#  6. Switch-over (if chosen): shuts ALL qubes down, points every disposable
#     template at its f44-* template, makes every configured sys- qube a named
#     disposable (app qubes kept as <name>-old, settings copied), and starts the
#     sys- qubes that were running.
#  7. The chosen modules that make their own qubes: their settings, the setup
#     inside them and their dom0 policy (rules for existing qubes: see the
#     shared helpers below).
#  8. Enables the watcher, so every later base update triggers a rebuild.

set -euo pipefail

[ "$(hostname)" = dom0 ] || { echo "run this in dom0" >&2; exit 1; }
[ "$(id -u)" -ne 0 ] || { echo "run as your normal dom0 user, not root/sudo" >&2; exit 1; }
[ -t 0 ] || { echo "run this in a terminal: it asks questions first" >&2; exit 1; }

BIN=~/.local/bin
CONF_DIR=~/.config/minimal-templating
CONF=$CONF_DIR/templates.conf
UNIT_DIR=~/.config/systemd/user
STATE_DIR=~/.local/state/minimal-templating
UNIT=minimal-templating-listen.service
D=/etc/minimal-templating
RC_DIRS="/rw/config/rc.local.d /rw/config/rc.local-early.d"
TPL_PREFIX=f44-
WARNED=0
declare -A KEEP=()

F_MAIN=$(cat <<'__END_F_MAIN__'
#!/usr/bin/python3
# minimal-templating - build and refresh minimal derived templates from one base (dom0).
#
# Install in dom0 as ~/.local/bin/minimal-templating (chmod +x).
# Config: ~/.config/minimal-templating/templates.conf
# Log:    ~/.local/state/minimal-templating/minimal-templating.log  (also stdout)
#
# Each config section describes one stack, top to bottom:
#   [template]       derived template, cloned from the base and stripped
#   dvm  = <name>    disposable template on that template           (optional)
#   qube = <name>    qube on top:                                    (optional)
#                      dvm set   -> named disposable based on the dvm
#                      dvm blank -> standard app qube based on the template
#   qube blank + dvm set -> the dvm is for unnamed disposables (dispNNNN)
#
# The lists used are /etc/minimal-templating/<list>.dnf / .flatpak in the base,
# where <list> is the qube name, or the dvm name when qube is blank.
#
# Optional shared template (off by default): one template serving several
# stacks whose lists would make identical templates. Step-by-step directions,
# with an example, are at the top of templates.conf.
#
# Each run:
#   1. Starts the base once to see which lists exist. Sections without a .dnf
#      list are skipped (logged), so you can add one before writing its list.
#   2. For each section that has a list:
#      - template missing  -> clone it from the base (label black)
#        template existing -> replace its root with a thin snapshot of the base's root
#      - keep no previous versions (revisions_to_keep 0), set skip-update=1
#      - run /etc/minimal-templating/apply inside it as root; it strips the
#        template and then deletes itself and the lists. Then shut it down.
#      - on success: create the dvm (black) and qube (red) if missing, and point
#        existing ones at the right template (halted ones only). Nothing else is
#        set: netvm, firewall, devices etc. stay at Qubes defaults.
#      - on failure: logged. The template is left half-stripped: fix the lists and
#        rerun 'minimal-templating --only <template>' before restarting its qubes.
#   3. One notification: "Templating process completed".
#
# Parallel builds ('parallel' in [general] of templates.conf, default 2): up to
# that many templates build at once. Only one starts up at a time, so one boots
# while another runs dnf. If Qubes can't give a second build memory without
# squeezing running qubes below what they need, it waits for the running build
# to finish and continues one at a time. Each template's log lines are kept
# together: collected in memory while it builds, written as one block when done.
#
# Usage:
#   minimal-templating            build/refresh everything now
#   minimal-templating --auto     only if the base's last-update changed since the
#                                 last run (used by the listener)
#   minimal-templating --only f44-sys-net [--only ...]
#   minimal-templating --preview  run 'apply --dry-run' for every section inside the
#                                 base itself (changes nothing) and log the plans
#   minimal-templating --status   show every stack and its state (starts nothing)
#   minimal-templating --switch   one-time move of the configured named disposables
#                                 onto their stacks: shows a plan, asks y/N, shuts
#                                 ALL qubes down, then points every disposable
#                                 template at its f44-* template, and for each
#                                 named disposable:
#                                   missing           -> create it
#                                   named disposable  -> point it at its dvm
#                                   app qube          -> keep it as <name>-old (or
#                                     -old-2, ... if taken) and create a named
#                                     disposable in its place, copying
#                                     netvm, provides_network, autostart, memory,
#                                     services, firewall rules and PCI devices, and
#                                     re-pointing every qube/global setting that used it
#                                 then starts again the named disposables that were
#                                 running. Safe to re-run: it only does what's needed.

import argparse
import configparser
import fcntl
import os
import re
import subprocess
import sys
import threading
import time
from concurrent.futures import ThreadPoolExecutor

import qubesadmin

CONF = os.path.expanduser("~/.config/minimal-templating/templates.conf")
STATE_DIR = os.path.expanduser("~/.local/state/minimal-templating")
LOG = os.path.join(STATE_DIR, "minimal-templating.log")
STAMP = os.path.join(STATE_DIR, "last-update")
BUILT_DIR = os.path.join(STATE_DIR, "built")
LOCK = os.path.join(STATE_DIR, "lock")
DIR = "/etc/minimal-templating"
APPLY = f"{DIR}/apply"
RUN_TIMEOUT = 1800          # seconds for apply inside a template
HALT_TIMEOUT = 180
DEFAULT_PARALLEL = 2        # templates built at once ('parallel' in templates.conf)
MAX_PARALLEL = 4
NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]*$")

# Labels for qubes this script creates (existing qubes are never relabelled).
LABEL_TEMPLATE = "black"
LABEL_DVM = "black"
LABEL_NAMED_DISP = "red"
LABEL_APPVM = "red"


_LOG_LOCK = threading.Lock()
_local = threading.local()      # per-worker log buffer during parallel builds


def _write(lines):
    """Print lines and append them to the log file, as one uninterrupted block."""
    with _LOG_LOCK:
        for line in lines:
            print(line, flush=True)
        with open(LOG, "a", encoding="utf-8") as f:
            f.write("".join(line + "\n" for line in lines))


def log(msg):
    line = time.strftime("%Y-%m-%d %H:%M:%S ") + msg
    buf = getattr(_local, "buf", None)
    if buf is not None:         # inside a parallel build: keep its lines together
        buf.append(line)
        return
    _write([line])


def progress(msg):
    """A live one-line status on stdout (the journal) only, not the log file."""
    with _LOG_LOCK:
        print(time.strftime("%Y-%m-%d %H:%M:%S ") + msg, flush=True)


def notify(summary, body=""):
    try:
        subprocess.run(["notify-send", "-a", "minimal-templating", summary, body],
                       timeout=10, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def clean(text, limit=20000):
    """Template output is untrusted: keep printable characters only, cap length."""
    text = "".join(c if (c.isprintable() or c == "\n") else "?" for c in text)
    return text[:limit]


def load_config():
    """Each section becomes a stack: {template, list, members}. A member is one
    {template, dvm, qube} triple. Normally a stack has one member; a shared
    template (several names in dvm/qube) has one member per position."""
    cp = configparser.ConfigParser()
    if not cp.read(CONF):
        sys.exit(f"missing config {CONF}")
    base = cp.get("general", "base")
    raw = cp.get("general", "parallel", fallback=str(DEFAULT_PARALLEL)).strip()
    if not raw.isdigit() or not 1 <= int(raw) <= MAX_PARALLEL:
        sys.exit(f"[general] parallel = {raw!r}: use a whole number from 1 to {MAX_PARALLEL}")
    parallel = int(raw)
    stacks, seen = [], {}
    for sect in cp.sections():
        if sect == "general":
            continue
        dvms = cp.get(sect, "dvm", fallback="").split()
        qubes = cp.get(sect, "qube", fallback="").split()
        lst = cp.get(sect, "list", fallback="").strip()
        if not dvms and not qubes:
            sys.exit(f"[{sect}]: set qube, dvm, or both")
        shared = len(dvms) > 1 or len(qubes) > 1
        if shared and not lst:
            sys.exit(f"[{sect}]: a shared template needs 'list = <name>' (which lists to use)")
        if dvms and qubes and len(dvms) != len(qubes):
            sys.exit(f"[{sect}]: give one qube per dvm (paired in order), or leave qube blank")
        if dvms:
            members = [{"template": sect, "dvm": d, "qube": qubes[i] if qubes else ""}
                       for i, d in enumerate(dvms)]
        else:
            members = [{"template": sect, "dvm": "", "qube": q} for q in qubes]
        lst = lst or (qubes[0] if qubes else dvms[0])
        for n in [sect, lst, *dvms, *qubes]:
            if not NAME_RE.match(n):
                sys.exit(f"invalid name {n!r} in section [{sect}]")
        for n in [sect, *dvms, *qubes]:
            if n in seen:
                sys.exit(f"{n!r} appears in both [{seen[n]}] and [{sect}]")
            seen[n] = sect
        stacks.append({"template": sect, "list": lst, "members": members})
    return base, stacks, parallel


def shutdown(vm):
    """Shut down and wait until Qubes has finished saving the qube's disk.
    qvm-shutdown --wait returns only after the shutdown is fully processed;
    polling is_halted() alone can return before a template's root is committed,
    and a clone taken then would copy the previous version."""
    if not vm.is_running():
        return
    r = subprocess.run(["qvm-shutdown", "--wait", "--timeout", str(HALT_TIMEOUT), vm.name],
                       capture_output=True, text=True)
    if r.returncode != 0:
        log(f"  {vm.name}: did not shut down in {HALT_TIMEOUT}s, killing")
        subprocess.run(["qvm-kill", vm.name], capture_output=True)
        time.sleep(3)
    time.sleep(2)   # small margin for storage bookkeeping


def run_in(vm_name, command):
    cmd = ["qvm-run", "--user", "root", "--pass-io", "--no-gui", vm_name, command]
    try:
        r = subprocess.run(cmd, capture_output=True, timeout=RUN_TIMEOUT)
    except subprocess.TimeoutExpired:
        return 124, f"timed out after {RUN_TIMEOUT}s"
    out = (r.stdout + r.stderr).decode("utf-8", errors="replace")
    return r.returncode, clean(out)


def stacks_with_lists(base, stacks):
    """Ask the base which lists exist. The answer is only ever intersected with
    names from the config, so the template can't make dom0 create anything that
    isn't already there."""
    checks = "; ".join(f"test -f {DIR}/{s['list']}.dnf && echo {s['list']}"
                       for s in stacks)
    _, out = run_in(base.name, checks + "; true")
    shutdown(base)
    found = set(out.split())
    return [s for s in stacks if s["list"] in found]


def prepare_template(app, base, name):
    """Return the derived template with a fresh copy of the base's root."""
    if name in app.domains:
        tpl = app.domains[name]
        if tpl.klass != "TemplateVM":
            raise RuntimeError(f"{name} exists but is a {tpl.klass}, not a TemplateVM")
        if not tpl.is_halted():
            raise RuntimeError(f"{name} is running; not refreshed (will retry next rebuild)")
        tpl.volumes["root"].revisions_to_keep = 0
        tpl.volumes["root"].clone(base.volumes["root"])
        log(f"  {name}: root refreshed from {base.name}")
    else:
        tpl = app.clone_vm(base, name)
        tpl.label = LABEL_TEMPLATE
        tpl.volumes["root"].revisions_to_keep = 0
        log(f"  {name}: created as clone of {base.name}")
    tpl.features["skip-update"] = "1"
    return tpl


def set_template(vm, want):
    """Point an existing qube at 'want' if it isn't already (halted qubes only)."""
    current = getattr(vm, "template", None)
    if current is not None and str(current) == want:
        return
    if not vm.is_halted():
        log(f"  WARN {vm.name} is running; not switched to {want} (shut it down and rerun)")
        return
    try:
        vm.template = want
    except Exception as e:
        # e.g. a disposable template whose disposables are still running
        log(f"  WARN {vm.name} not switched to {want}: {e} "
            f"(shut those down, then: qvm-prefs {vm.name} template {want})")
        return
    log(f"  {vm.name}: template -> {want}")


def ensure_dvm(app, s):
    name = s["dvm"]
    if name not in app.domains:
        vm = app.add_new_vm("AppVM", name, LABEL_DVM, template=s["template"])
        vm.template_for_dispvms = True
        log(f"  {name}: created disposable template on {s['template']}")
        return
    vm = app.domains[name]
    if vm.klass != "AppVM" or not vm.template_for_dispvms:
        log(f"  WARN {name} exists but is not a disposable template; left unchanged")
        return
    set_template(vm, s["template"])


def ensure_qube(app, s):
    name = s["qube"]
    if s["dvm"]:
        klass, label, want = "DispVM", LABEL_NAMED_DISP, s["dvm"]
    else:
        klass, label, want = "AppVM", LABEL_APPVM, s["template"]
    if name not in app.domains:
        app.add_new_vm(klass, name, label, template=want)
        kind = "named disposable" if klass == "DispVM" else "app qube"
        log(f"  {name}: created {kind} on {want}")
        return
    vm = app.domains[name]
    if vm.klass != klass:
        log(f"  WARN {name} exists as {vm.klass}, config expects {klass}; left unchanged")
        return
    set_template(vm, want)


def mark_built(name):
    os.makedirs(BUILT_DIR, exist_ok=True)
    with open(os.path.join(BUILT_DIR, name), "w", encoding="utf-8") as f:
        f.write(time.strftime("%Y-%m-%d %H:%M") + "\n")


_BOOT_LOCK = threading.Lock()   # one template starts up at a time
_ACTIVE = 0                     # builds currently running a template
_ACTIVE_CV = threading.Condition()


def start_for_build(vm):
    """Start a template for its build, one start-up at a time, so one template
    boots while another runs dnf. Qubes only starts a qube if it can give it
    memory while every running qube keeps what it needs; if it refuses while
    another build is running, wait for the running builds to finish and try
    once more, i.e. carry on one at a time."""
    global _ACTIVE
    with _BOOT_LOCK:
        for attempt in (1, 2):
            r = subprocess.run(["qvm-start", "--skip-if-running", vm.name],
                               capture_output=True, text=True)
            if r.returncode == 0:
                with _ACTIVE_CV:
                    _ACTIVE += 1
                return True
            err = clean((r.stderr or r.stdout or "").strip(), 300)
            with _ACTIVE_CV:
                busy = _ACTIVE > 0
            if attempt == 1 and busy and "memory" in err.lower():
                log(f"  {vm.name}: not enough memory next to the running build; "
                    f"waiting for it to finish, then building one at a time")
                with _ACTIVE_CV:
                    _ACTIVE_CV.wait_for(lambda: _ACTIVE == 0,
                                        timeout=RUN_TIMEOUT + HALT_TIMEOUT)
                continue
            log(f"  {vm.name}: could not start: {err}")
            return False
    return False


def end_build():
    global _ACTIVE
    with _ACTIVE_CV:
        _ACTIVE -= 1
        _ACTIVE_CV.notify_all()


def rebuild_one(app, base, s):
    name = s["template"]
    tpl = prepare_template(app, base, name)
    if not start_for_build(tpl):
        log(f"  {name}: FAILED: could not start it, so it was not stripped (it is a full "
            f"copy of the base): run minimal-templating --only {name}")
        return False
    try:
        rc, out = run_in(name, f"{APPLY} --in {name} {s['list']}")
        for line in out.splitlines():
            log(f"  | {line}")
        shutdown(tpl)
    finally:
        end_build()
    if rc in (126, 127):
        log(f"  {name}: FAILED: {APPLY} not found in the clone (exit {rc}); nothing "
            f"was stripped. Re-run the installer, then: minimal-templating --only {name}")
        return False
    if rc != 0:
        log(f"  {name}: apply FAILED (exit {rc}); template is half-stripped, "
            f"fix the lists and run: minimal-templating --only {name}")
        return False
    for m in s["members"]:
        if m["dvm"]:
            ensure_dvm(app, m)
        if m["qube"]:
            ensure_qube(app, m)
    mark_built(name)
    log(f"  {name}: OK")
    return True


def build_stack(base_name, s, buffered):
    """One template's whole build, run by a worker. With buffered=True (parallel
    builds) its log lines are collected in memory and written as one block when
    it finishes; a short live line marks the start. Never raises."""
    if buffered:
        _local.buf = []
        progress(f"{s['template']}: building")
    ok = False
    try:
        app = qubesadmin.Qubes()        # each worker has its own connection to qubesd
        base = app.domains[base_name]
        log(f"{s['template']} (list {s['list']}):")
        ok = rebuild_one(app, base, s)
    except Exception as e:
        log(f"  {s['template']}: ERROR {e}")
    finally:
        if buffered:
            lines, _local.buf = _local.buf, None
            _write(lines)
    return ok


def preview(base, stacks):
    for s in stacks:
        log(f"preview {s['template']} (list {s['list']}):")
        _, out = run_in(base.name, f"{APPLY} --dry-run {s['list']}")
        for line in out.splitlines():
            log(f"  | {line}")
    shutdown(base)


def status(app, base_name, stacks, parallel=DEFAULT_PARALLEL):
    """Print each stack's state from dom0's view. Starts nothing."""
    def describe(name, want_klass, want_template=None, dvm=False):
        if not name:
            return "-"
        if name not in app.domains:
            return f"{name} (missing)"
        vm = app.domains[name]
        if vm.klass != want_klass:
            return f"{name} (is {vm.klass}, expected {want_klass})"
        if dvm and not vm.template_for_dispvms:
            return f"{name} (not a disposable template)"
        if want_template:
            cur = str(getattr(vm, "template", ""))
            if cur != want_template:
                return f"{name} (on {cur}, expected {want_template})"
        return f"{name} ok"

    base = app.domains[base_name] if base_name in app.domains else None
    last = base.features.get("last-update", "") if base else ""
    try:
        with open(STAMP, encoding="utf-8") as f:
            done = f.read().strip()
    except FileNotFoundError:
        done = None
    print(f"base {base_name}: last-update {last or '?'}"
          + ("" if last == done else "  -> rebuild pending"))
    print(f"builds: up to {parallel} at a time")
    print()
    for s in stacks:
        t = s["template"]
        try:
            with open(os.path.join(BUILT_DIR, t), encoding="utf-8") as f:
                built = f.read().strip()
        except FileNotFoundError:
            built = "never"
        if t not in app.domains:
            tstate = "missing"
        elif app.domains[t].klass != "TemplateVM":
            tstate = f"is {app.domains[t].klass}, not a TemplateVM"
        else:
            tstate = "ok" + ("" if app.domains[t].features.get("skip-update") else ", skip-update NOT set")
        shared = "  (shared)" if len(s["members"]) > 1 else ""
        print(f"[{t}]  template {tstate}, last built {built}, list {s['list']}{shared}")
        for m in s["members"]:
            if m["dvm"]:
                print(f"    dvm   {describe(m['dvm'], 'AppVM', t, dvm=True)}")
            if m["qube"]:
                if m["dvm"]:
                    print(f"    qube  {describe(m['qube'], 'DispVM', m['dvm'])}  (named disposable)")
                else:
                    print(f"    qube  {describe(m['qube'], 'AppVM', t)}  (app qube)")
            elif m["dvm"]:
                print("    qube  - (unnamed disposables)")


# ----------------------------------------------------------------- switch-over
# Prefs copied to a replacement named disposable when explicitly set on the old
# qube (not left at their default). Label is not copied: new ones are red.
COPY_PREFS = ("netvm", "provides_network", "autostart", "memory", "maxmem", "vcpus",
              "kernelopts", "virt_mode", "include_in_backups", "default_dispvm",
              "qrexec_timeout", "shutdown_timeout")
GLOBAL_PREFS = ("default_netvm", "updatevm", "clockvm")


def explicit(obj, prop):
    try:
        return not obj.property_is_default(prop)
    except Exception:
        return False


def copy_settings(src, dst):
    """Carry over what makes a sys- qube work. Returns a list of things that
    could not be copied, for the user to set in Qube Manager."""
    missed = []
    for p in COPY_PREFS:
        if explicit(src, p):
            try:
                setattr(dst, p, getattr(src, p))
            except Exception as e:
                missed.append(f"pref {p} ({e})")
    for k in list(src.features):
        if k.startswith("service."):
            dst.features[k] = src.features[k]
    try:
        rules = src.firewall.rules
        if rules:
            dst.firewall.rules = rules
    except Exception as e:
        missed.append(f"firewall rules ({e})")
    try:
        for a in src.devices["pci"].get_assigned_devices():
            dst.devices["pci"].assign(a.clone(frontend_domain=dst))
    except Exception as e:
        missed.append(f"PCI devices ({e})")
    return missed


def free_old_name(app, name):
    """<name>-old, or <name>-old-2, -old-3, ... if that is taken."""
    old, i = f"{name}-old", 2
    while old in app.domains:
        old, i = f"{name}-old-{i}", i + 1
    return old


BACKUPS = {}   # qube -> the name its old app qube was kept under, this run


def replace_with_named_disposable(app, s):
    """Replace an app-qube sys- qube with a named disposable of the same name.
    The old one is kept, shut down and not autostarting, as <name>-old (or
    -old-2, ... if that name is taken). Until the new one exists, everything that
    used the old qube points at the backup, so a failure part-way leaves a
    working system."""
    name, dvm = s["qube"], s["dvm"]
    old = free_old_name(app, name)
    BACKUPS[name] = old
    src = app.domains[name]
    autostart = src.autostart        # copied from the backup below, after it is turned off there

    backup = app.clone_vm(src, old)
    backup.autostart = False
    log(f"  {name}: backed up as {old} (autostart off)")

    moved_vms = [vm for vm in app.domains
                 if vm.name not in (name, old) and hasattr(vm, "netvm")
                 and explicit(vm, "netvm") and str(vm.netvm) == name]
    moved_globals = [p for p in GLOBAL_PREFS if str(getattr(app, p, "")) == name]
    for vm in moved_vms:
        vm.netvm = old
    for p in moved_globals:
        setattr(app, p, old)

    del app.domains[name]
    new = app.add_new_vm("DispVM", name, LABEL_NAMED_DISP, template=dvm)
    missed = copy_settings(backup, new)
    if autostart:
        new.autostart = True

    for vm in moved_vms:
        vm.netvm = name
    for p in moved_globals:
        setattr(app, p, name)
    log(f"  {name}: now a named disposable on {dvm}; re-pointed "
        f"{len(moved_vms)} qube(s){' and ' + ', '.join(moved_globals) if moved_globals else ''}")
    for m in missed:
        log(f"  WARN {name}: could not copy {m}; set it in Qube Manager (see {old})")
    return True


def switch(app, stacks, assume_yes):
    """Move every configured named disposable onto its stack: shut all qubes
    down, re-point or replace, then start again what was running."""
    todo, dvm_todo, named = [], [], []
    for s in (m for st in stacks for m in st["members"]):
        if not s["dvm"]:
            continue
        tpl = app.domains[s["template"]] if s["template"] in app.domains else None
        dvm = app.domains[s["dvm"]] if s["dvm"] in app.domains else None
        if tpl is None or tpl.klass != "TemplateVM" or dvm is None or not dvm.template_for_dispvms:
            log(f"{s['qube'] or s['dvm']}: SKIPPED, {s['template']} / {s['dvm']} not built yet "
                f"(run minimal-templating first)")
            continue
        # Disposable templates can only be re-pointed while none of their
        # disposables run, which is why this happens here and not in the build.
        if str(dvm.template) != s["template"]:
            dvm_todo.append(s)
        if not s["qube"]:
            continue
        named.append(s["qube"])
        if s["qube"] not in app.domains:
            todo.append((s, "create"))
            continue
        vm = app.domains[s["qube"]]
        if vm.klass == "DispVM":
            if str(vm.template) != s["dvm"]:
                todo.append((s, "repoint"))
        elif vm.klass == "AppVM":
            todo.append((s, "replace"))
        else:
            log(f"{s['qube']}: SKIPPED, is a {vm.klass}")
    if not todo and not dvm_todo:
        log("switch: nothing to do, everything is on its stack")
        return 0

    print("\nSwitch-over plan:")
    for s in dvm_todo:
        print(f"  {s['dvm']:16} point at {s['template']} (now on {app.domains[s['dvm']].template})")
    for s, action in todo:
        desc = {"create": f"create named disposable on {s['dvm']}",
                "repoint": f"point at {s['dvm']}",
                "replace": f"replace app qube with named disposable on {s['dvm']}; "
                           f"old one kept as {free_old_name(app, s['qube'])}"}[action]
        print(f"  {s['qube']:16} {desc}")
    print("\nThis shuts down ALL running qubes first (save your work), then starts")
    print("the ones from this plan that were running again.")
    if not assume_yes:
        if input("Continue? [y/N] ").strip().lower() not in ("y", "yes"):
            print("cancelled, nothing changed")
            return 1

    was_running = {vm.name for vm in app.domains
                   if vm.name != "dom0" and vm.is_running()}
    log(f"switch: shutting down all qubes ({len(was_running)} running)")
    subprocess.run(["qvm-shutdown", "--all", "--wait", "--timeout", "300"])

    failed = []
    for s in dvm_todo:
        try:
            app.domains[s["dvm"]].template = s["template"]
            log(f"  {s['dvm']}: template -> {s['template']}")
        except Exception as e:
            log(f"  {s['dvm']}: ERROR {e}")
            failed.append(s["dvm"])
    for s, action in todo:
        try:
            if action == "create":
                app.add_new_vm("DispVM", s["qube"], LABEL_NAMED_DISP, template=s["dvm"])
                log(f"  {s['qube']}: created named disposable on {s['dvm']}")
            elif action == "repoint":
                app.domains[s["qube"]].template = s["dvm"]
                log(f"  {s['qube']}: template -> {s['dvm']}")
            elif not replace_with_named_disposable(app, s):
                failed.append(s["qube"])
        except Exception as e:
            log(f"  {s['qube']}: ERROR {e}")
            failed.append(s["qube"])

    for q in named:
        start = q if q in app.domains else BACKUPS.get(q, f"{q}-old")
        if q in was_running and start in app.domains:
            r = subprocess.run(["qvm-start", "--skip-if-running", start],
                               capture_output=True, text=True)
            log(f"  started {start}" if r.returncode == 0
                else f"  WARN could not start {start}: {r.stderr.strip()[:200]}")

    msg = "switch-over done" + (f", FAILED: {' '.join(failed)}" if failed else "")
    log(msg)
    notify("Switch-over completed", msg + f"\nSee {LOG}")
    return 1 if failed else 0


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--auto", action="store_true")
    ap.add_argument("--only", action="append", default=[])
    ap.add_argument("--preview", action="store_true")
    ap.add_argument("--status", action="store_true")
    ap.add_argument("--switch", action="store_true")
    ap.add_argument("--yes", action="store_true")
    args = ap.parse_args()

    os.makedirs(STATE_DIR, exist_ok=True)
    base_name, stacks, parallel = load_config()
    if args.only:
        stacks = [s for s in stacks if s["template"] in args.only]
        if not stacks:
            sys.exit("no matching sections for --only")

    app = qubesadmin.Qubes()

    if args.status:
        status(app, base_name, stacks, parallel)
        return 0

    lockf = open(LOCK, "w")
    try:
        fcntl.flock(lockf, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        print("minimal-templating already running", flush=True)
        return 0

    if args.switch:
        return switch(app, stacks, args.yes)

    base = app.domains[base_name]

    if args.preview:
        preview(base, stacks)
        return 0

    if not base.is_halted():
        print(f"{base_name} is running; rebuild waits for its shutdown", flush=True)
        return 0

    last_update = base.features.get("last-update", "") or ""
    try:
        with open(STAMP, encoding="utf-8") as f:
            previous = f.read().strip()
    except FileNotFoundError:
        previous = None
    if args.auto and last_update == previous:
        return 0

    log(f"rebuild start: {base_name} last-update={last_update!r} previous={previous!r}")
    ready = stacks_with_lists(base, stacks)
    for s in stacks:
        if s not in ready:
            log(f"{s['template']}: skipped, no {DIR}/{s['list']}.dnf in {base_name}")

    workers = max(1, min(parallel, len(ready)))
    buffered = workers > 1
    if buffered:
        log(f"building {len(ready)} templates, up to {workers} at a time")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        results = list(pool.map(lambda s: build_stack(base_name, s, buffered), ready))
    failed = [s["template"] for s, ok in zip(ready, results) if not ok]

    # Record this base version as handled even if some failed: failures are
    # fixed and rerun by hand, and the listener must not retry in a loop.
    if not args.only:
        with open(STAMP, "w", encoding="utf-8") as f:
            f.write(last_update + "\n")

    # The one notification per run.
    ok = len(ready) - len(failed)
    if failed:
        log(f"rebuild finished: {ok} OK, failed: {' '.join(failed)}")
        notify("Templating process completed",
               f"{ok} OK, {len(failed)} FAILED: {' '.join(failed)}\n"
               f"Don't restart their qubes until fixed. See {LOG}")
        return 1
    log(f"rebuild finished: {ok} templates OK")
    notify("Templating process completed", f"{ok} templates OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
__END_F_MAIN__
)
F_LISTEN=$(cat <<'__END_F_LISTEN__'
#!/usr/bin/python3
# minimal-templating-listen - run minimal-templating after the base template is updated (dom0).
#
# Install as ~/.local/bin/minimal-templating-listen (chmod +x), started by the systemd
# user unit minimal-templating-listen.service. Idle cost: one small Python process
# blocked on the qubesd event socket.
#
# Triggers 'minimal-templating --auto' (which itself checks that the base is halted and
# that its last-update feature changed) on:
#   - listener start (catches updates made while it wasn't running)
#   - the base template shutting down (the updater shuts it down when done)
#   - the base's last-update feature being set

import asyncio
import configparser
import os
import sys

import qubesadmin
import qubesadmin.events

REBUILD = os.path.expanduser("~/.local/bin/minimal-templating")
CONF = os.path.expanduser("~/.config/minimal-templating/templates.conf")
DELAY = 20      # seconds to let the updater finish writing features


class Trigger:
    def __init__(self):
        self.task = None
        self.again = False

    def fire(self, why):
        print(f"event: {why}", flush=True)
        if self.task and not self.task.done():
            self.again = True          # run once more after the current one
            return
        self.task = asyncio.get_running_loop().create_task(self._run())

    async def _run(self):
        while True:
            self.again = False
            await asyncio.sleep(DELAY)
            proc = await asyncio.create_subprocess_exec(REBUILD, "--auto")
            await proc.wait()
            if not self.again:
                return


async def main():
    cp = configparser.ConfigParser()
    if not cp.read(CONF):
        sys.exit(f"missing config {CONF}")
    base = cp.get("general", "base")

    trig = Trigger()
    trig.fire("startup")

    def on_event(subject, event, **kwargs):
        if subject is not None and str(subject) == base:
            trig.fire(f"{event} {base}")

    while True:
        try:
            app = qubesadmin.Qubes()
            disp = qubesadmin.events.EventsDispatcher(app)
            disp.add_handler("domain-shutdown", on_event)
            disp.add_handler("domain-feature-set:last-update", on_event)
            await disp.listen_for_events()
        except Exception as e:
            print(f"event stream error: {e}; reconnecting in 30s", file=sys.stderr, flush=True)
        await asyncio.sleep(30)


if __name__ == "__main__":
    asyncio.run(main())
__END_F_LISTEN__
)
F_CONF=$(cat <<'__END_F_CONF__'
# ~/.config/minimal-templating/templates.conf  (dom0)
#
# Lists which minimal templates to build from the base, and which qubes go on
# each one. 'minimal-templating' reads this file on every run (and the watcher
# runs it after every base update). The setup script never overwrites it once
# it exists; its latest default is kept next to it as templates.conf.example.
#
# ============================================================ HOW A SECTION WORKS
#
#   [f44-sys-net]          <- the derived template (cloned from the base, stripped)
#   dvm  = sys-net-dvm     <- disposable template on it                 (optional)
#   qube = sys-net         <- qube on top                               (optional)
#
#   dvm set,   qube set   -> qube is a NAMED DISPOSABLE based on dvm   (e.g. sys-net)
#   dvm blank, qube set   -> qube is a standard APP QUBE on the template (e.g. email)
#   dvm set,   qube blank -> dvm is for UNNAMED disposables (dispNNNN)  (e.g. default-dvm)
#
# Packages: each section uses two lists inside the base template, in
# /etc/minimal-templating/:
#   <qube>.dnf      RPMs this template keeps from master.dnf   (required)
#   <qube>.flatpak  Flatpak apps it keeps                     (optional; none if missing)
# named after the qube, or after the dvm when qube is blank. A section whose
# .dnf list doesn't exist yet is skipped, so you can add the section first.
#
# Missing qubes are created: template black, dvm black, named disposable and
# app qube red. Nothing else is set (netvm, firewall, devices, memory): change
# those in Qube Manager. Existing qubes are only re-pointed at their template,
# and only if they are the expected type and shut down.
#
# ============================================================ TO ADD A QUBE
#
#   1. In the base template, as root: add any packages it needs to master.dnf
#      and install them, then write /etc/minimal-templating/<qube>.dnf (and
#      <qube>.flatpak if it keeps Flatpak apps; its .dnf must then keep flatpak).
#      Shut the base down.
#      NOTE: re-running the setup script rewrites master.dnf and the five sys-
#      lists in the base (other lists are kept), so packages you add to
#      master.dnf by hand must also go into the setup script's master list.
#   2. Here: add a section, e.g.
#        [f44-email]
#        dvm =
#        qube = email
#   3. In dom0:  minimal-templating --preview --only f44-email   (dry run)
#                minimal-templating --only f44-email             (build it)
#
# ============================================================ OPTIONAL: SHARE ONE TEMPLATE
#
# Off by default. When two stacks would produce identical templates (their
# lists keep exactly the same packages, e.g. sys-firewall and sys-killswitch
# both keep only qubes-core-agent-networking), one template can serve both.
# Each qube still has its own disposable template, so its /rw files and boot
# scripts stay separate; only the template underneath is shared.
#
#   1. Replace their separate sections with one section:
#        [f44-net-minimal]
#        list = sys-firewall
#        dvm  = sys-firewall-dvm sys-killswitch-dvm
#        qube = sys-firewall     sys-killswitch
#      list = whose .dnf/.flatpak lists build it (required when sharing)
#      dvm  = several disposable templates, all placed on the shared template
#      qube = the qubes paired with them IN THE SAME ORDER (or leave it blank;
#             for app qubes, leave dvm blank and list several qubes here)
#   2. Shut down the qubes and dvms involved, then run:
#        minimal-templating --only f44-net-minimal
#      It builds the shared template and re-points both dvms at it.
#   3. Check with 'minimal-templating --status' (it marks the stack "shared"),
#      then remove the old, now unused templates:
#        qvm-remove f44-sys-firewall f44-sys-killswitch
#
#   To undo: put the separate sections back, run 'minimal-templating', and
#   remove f44-net-minimal once nothing uses it.
#
# The script refuses a config with no 'list' on a shared section, unequal
# numbers of dvms and qubes, or a name used in two sections, and says why.

[general]
base = fedora-44-minimal

# How many templates to build at once (1 to 4). Default 2: only one starts up
# at a time, so one boots while another runs dnf, which cuts a rebuild of five
# templates by about a third. Each template's log lines are still kept together.
# If Qubes can't give a second build memory without squeezing your running
# qubes, it waits and carries on one at a time by itself.
#
# Choose 1 if you'd rather never have two building templates running at once:
# a rebuild then takes longer, but uses at most one template's worth of memory
# (a few hundred MB), leaves more for whatever you are doing while it runs, and
# its log reads strictly in order as it happens. Above 2 gains little: the dnf
# steps start competing for the same disk.
parallel = 2

[f44-sys-net]
dvm = sys-net-dvm
qube = sys-net

[f44-sys-firewall]
dvm = sys-firewall-dvm
qube = sys-firewall

[f44-sys-killswitch]
dvm = sys-killswitch-dvm
qube = sys-killswitch

[f44-sys-vpn]
dvm = sys-vpn-dvm
qube = sys-vpn

[f44-sys-usb]
dvm = sys-usb-dvm
qube = sys-usb
__END_F_CONF__
)
F_UNIT=$(cat <<'__END_F_UNIT__'
# ~/.config/systemd/user/minimal-templating-listen.service  (dom0)
[Unit]
Description=Rebuild minimal templates after the base template is updated

[Service]
ExecStart=%h/.local/bin/minimal-templating-listen
Restart=on-failure
RestartSec=30
Nice=10
# Covers the idle listener (~30-40 MB) plus a running rebuild and its qvm-run calls.
MemoryMax=256M

[Install]
WantedBy=default.target
__END_F_UNIT__
)
F_APPLY=$(cat <<'__END_F_APPLY__'
#!/usr/bin/python3 -I
# /etc/minimal-templating/apply - strip a derived template down to its allowlists.
#
# Lives in the BASE template (fedora-44-minimal) with the lists, in
# /etc/minimal-templating/ (root:root, script 0755). Every f44-* template is a
# clone of the base, so it starts with a copy; dom0's minimal-templating runs it
# there as root.
#
# Lists in /etc/minimal-templating/ (one name per line, '#' comments allowed):
#   master.dnf       every RPM you added on top of the template (the removable set)
#   <name>.dnf       RPMs from master.dnf this template keeps          (required)
#   <name>.flatpak   Flatpak app IDs this template keeps   (missing = keep none)
#
# Real run (only in a derived template, and only when --in matches its name):
#   First:     delete base-only hooks (the Flatpak update hook), so the dnf
#              transaction below can't trigger Flatpak downloads in this template
#   RPMs:      remove (master.dnf - <name>.dnf), plus dependents and unused deps
#   Flatpaks:  uninstall every installed app not in <name>.flatpak, then unused runtimes
#   Verify:    allowlisted packages still installed, removed ones gone; else exit 1
#   Clean up:  always, success or failure: delete /etc/minimal-templating (this
#              script and all lists), /var/log/dnf5.log*, and the template's
#              journal, so qubes based on it carry no trace of the mechanism.
#              The next rebuild starts from a fresh copy of the base anyway.
#
# Usage:
#   apply --dry-run NAME             show the plan and dnf's transaction; change nothing
#   apply --in TEMPLATE NAME         real run (called by dom0; don't run by hand)

import glob
import os
import re
import shutil
import subprocess
import sys

DIR = "/etc/minimal-templating"
DNF = ["dnf", "--disable-repo=*"]          # templates are offline; never touch repos
NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._+-]*$")
APPMENUS_HOOK = "/etc/qubes/post-install.d/10-qubes-core-agent-appmenus.sh"
# Hooks that must only ever run in the base template (removed from derived ones).
BASE_ONLY_HOOKS = ("/etc/qubes/post-install.d/05-flatpak-update.sh",)


class Fail(Exception):
    pass


def say(msg):
    print(f"apply: {msg}", flush=True)


def run(cmd):
    return subprocess.run(cmd, capture_output=True, text=True)


def read_list(name, required):
    path = os.path.join(DIR, name)
    if not os.path.exists(path):
        if required:
            raise Fail(f"missing list {path}")
        return set()
    items = set()
    with open(path, encoding="utf-8") as f:
        for n, line in enumerate(f, 1):
            s = line.split("#", 1)[0].strip()
            if not s:
                continue
            if not NAME_RE.match(s):
                raise Fail(f"{path}:{n}: invalid name {s!r}")
            items.add(s)
    return items


def installed_rpms(names):
    """Subset of names that are installed."""
    if not names:
        return set()
    r = run(["rpm", "-q", "--qf", "%{NAME}\n", *sorted(names)])
    return {l.strip() for l in r.stdout.splitlines()} & set(names)


def flatpak_apps():
    if not shutil.which("flatpak"):
        return set()
    r = run(["flatpak", "list", "--app", "--system", "--columns=application"])
    if r.returncode != 0:
        raise Fail(f"flatpak list failed: {r.stderr.strip()[:300]}")
    return set(r.stdout.split())


def qdb(key):
    r = run(["qubesdb-read", key])
    return r.stdout.strip() if r.returncode == 0 else ""


def strip(name, dry):
    master = read_list("master.dnf", True)
    keep = read_list(f"{name}.dnf", True)
    keep_fp = read_list(f"{name}.flatpak", False)

    present = installed_rpms(master)
    remove = sorted(present - keep)
    keep_present = present & keep
    apps = flatpak_apps()
    remove_fp = sorted(apps - keep_fp)

    say(f"list={name} remove_rpms={len(remove)} remove_flatpaks={len(remove_fp)}")
    if remove:
        say("rpms to remove (plus dependents and unused deps): " + " ".join(remove))
    if remove_fp:
        say("flatpaks to remove: " + " ".join(remove_fp))

    if dry:
        if remove:
            r = run(DNF + ["--assumeno", "remove", *remove])
            print(r.stdout + r.stderr, flush=True)
        say("dry run: no changes made")
        return

    # Flatpaks first: removing the flatpak RPM afterwards would strand the apps.
    if remove_fp:
        r = run(["flatpak", "uninstall", "--system", "-y", "--noninteractive", *remove_fp])
        if r.returncode != 0:
            raise Fail(f"flatpak uninstall failed: {r.stderr.strip()[:500]}")
        run(["flatpak", "uninstall", "--system", "-y", "--noninteractive", "--unused"])

    if remove:
        r = run(DNF + ["-y", "remove", *remove])
        print(r.stdout, flush=True)
        if r.returncode != 0:
            raise Fail(f"dnf remove failed: {r.stderr.strip()[:800]}")

    lost = sorted(keep_present - installed_rpms(keep_present))
    if lost:
        raise Fail("allowlisted packages were removed as dependents: " + " ".join(lost)
                   + " (add what they depend on to the allowlist)")
    left = sorted(installed_rpms(set(remove)))
    if left:
        raise Fail("packages still installed after removal: " + " ".join(left))

    if remove_fp and os.access(APPMENUS_HOOK, os.X_OK):
        run([APPMENUS_HOOK])   # dnf runs this hook itself; flatpak removal does not


def cleanup():
    """Remove every trace of minimal templating from this derived template."""
    shutil.rmtree(DIR, ignore_errors=True)
    for f in glob.glob("/var/log/dnf5.log*"):
        try:
            os.unlink(f)
        except OSError:
            pass
    run(["journalctl", "--rotate"])
    run(["journalctl", "--vacuum-time=1s"])
    say("cleaned up: removed /etc/minimal-templating, dnf5 logs and journal")


def main():
    args = sys.argv[1:]
    if len(args) == 2 and args[0] == "--dry-run":
        dry, target, name = True, None, args[1]
    elif len(args) == 3 and args[0] == "--in":
        dry, target, name = False, args[1], args[2]
    else:
        print("usage: apply --dry-run NAME | apply --in TEMPLATE NAME", file=sys.stderr)
        return 2
    if not NAME_RE.match(name):
        print(f"invalid name {name!r}", file=sys.stderr)
        return 2

    if not dry:
        # Safety: a real run destroys packages and deletes the lists, so it must
        # only ever happen in the derived template dom0 named, never in the base.
        if os.geteuid() != 0:
            say("FAIL must run as root")
            return 1
        if qdb("/name") != target or qdb("/qubes-vm-type") != "TemplateVM":
            say(f"FAIL refusing: this is not template {target!r}")
            return 1
        # Before any dnf transaction: hooks in post-install.d run after every
        # one, and the Flatpak update hook would download updates here.
        for hook in BASE_ONLY_HOOKS:
            if os.path.exists(hook):
                os.unlink(hook)
                say(f"removed base-only hook {hook}")

    try:
        strip(name, dry)
        rc = 0
        if not dry:
            say("OK")
    except Fail as e:
        say(f"FAIL {e}")
        rc = 1
    finally:
        if not dry:
            cleanup()
    return rc


if __name__ == "__main__":
    sys.exit(main())
__END_F_APPLY__
)
L_0=$(cat <<'__END_L_0__'
# Everything added on top of fedora-44-minimal. Each derived template keeps only
# what its own list names; everything else here is removed from it.

# admin convenience (removed from every derived template that does not list it)
xfce4-terminal
qubes-core-agent-passwordless-root

# file manager (kept where a list names it)
Thunar

# networking
qubes-core-agent-networking
qubes-core-agent-dom0-updates
qubes-core-agent-network-manager
NetworkManager-wifi
network-manager-applet
iwlwifi-mvm-firmware
iwlbluetooth-firmware

# notifications
notification-daemon
qubes-notification-agent

# USB
qubes-usb-proxy
__END_L_0__
)
