S_SYS_NET_WIFI=$(cat <<'__END_S_SYS_NET_WIFI__'
#!/bin/bash
# sys-net-wifi/setup.sh - remember Wi-Fi networks in a disposable net qube.
# GENERATED by tools/build.py from the plain files beside it: edit those, then rebuild.
#
# Run as root in the net qube's DISPOSABLE TEMPLATE (e.g. sys-net-dvm), not in
# the disposable itself. Either, inside the disposable template:
#   sudo bash setup.sh [--qube sys-net]
# or from dom0, after copying setup.sh into the disposable template:
#   qvm-run -u root -p sys-net-dvm 'bash /home/user/QubesIncoming/<qube>/setup.sh'
#
# Options:
#   --qube NAME   name of the net qube that should load the networks (default sys-net)
#
# Installs (re-running replaces the script and keeps saved networks):
#   /rw/config/rc.local-early.d/wifi-persistence.rc   0755  restores networks at boot
#   /usr/local/etc/nm-connections/                    0700  saved .nmconnection files
#
# Needs NetworkManager in the template (qubes-core-agent-network-manager).

set -euo pipefail

QUBE=sys-net
while [ $# -gt 0 ]; do
    case "$1" in
        --qube) QUBE=${2:?--qube needs a name}; shift 2 ;;
        -h|--help) sed -n '2,20p' "$0" 2>/dev/null || true; exit 0 ;;
        *) echo "unknown option: $1" >&2; exit 2 ;;
    esac
done
[[ $QUBE =~ ^[A-Za-z0-9][A-Za-z0-9_-]*$ ]] || { echo "invalid qube name: $QUBE" >&2; exit 2; }
[ "$(id -u)" -eq 0 ] || { echo "run as root (see the top of this file)" >&2; exit 1; }
if [ "$(qubesdb-read /qubes-vm-persistence 2>/dev/null || true)" = none ]; then
    echo "this is a disposable: anything installed here is lost at shutdown." >&2
    echo "run it in the disposable template instead (e.g. sys-net-dvm)." >&2
    exit 1
fi
command -v nmcli >/dev/null || echo "WARN: nmcli not found: the template needs NetworkManager" >&2

F_WIFI_PERSISTENCE_RC=$(cat <<'__END_F_WIFI_PERSISTENCE_RC__'
#!/bin/bash
# Restore saved Wi-Fi .nmconnection files into the disposable net qube.
# Installed by sys-net-wifi/setup.sh (or the all-in-one setup) in the net
# qube's disposable template, e.g. sys-net-dvm, as
#   /rw/config/rc.local-early.d/wifi-persistence.rc   (executable)
# together with the credential folder (mode 700):
#   /usr/local/etc/nm-connections
#
# After joining a new network in sys-net, save its .nmconnection into the dvm
# template from dom0 (neither qube has passwordless sudo, so do it as root via
# qvm-run; the file is piped straight through and never shown in dom0):
#   f='<network name>.nmconnection'
#   qvm-run -u root --pass-io sys-net "cat '/etc/NetworkManager/system-connections/$f'" |
#     qvm-run -u root --pass-io sys-net-dvm "umask 077; cat > '/usr/local/etc/nm-connections/$f'"
# The net qube's name is set below (setup.sh --qube NAME sets it for you).

set -euo pipefail
shopt -s nullglob

net_qube="sys-net"
nm_config_dir="/usr/local/etc/nm-connections"
nm_dest="/etc/NetworkManager/system-connections"

files=("$nm_config_dir"/*.nmconnection)
(( ${#files[@]} )) || exit 0

# Fast path: sys-net
if [ "$(qubesdb-read /name)" = "$net_qube" ]; then
    install -m 600 -o root -g root -Z -t "$nm_dest" -- "${files[@]}"
    rm -f -- "${files[@]}"
    # Normally a no-op since local-early.d runs before NetworkManager
    if systemctl is-active --quiet NetworkManager; then
        nmcli connection reload || true
    fi
    exit 0
fi

# Safety net: strip stored credentials from any other disposable
if [ "$(qubesdb-read /qubes-vm-persistence)" = "none" ]; then
    rm -f -- "${files[@]}"
fi
__END_F_WIFI_PERSISTENCE_RC__
)
F_WIFI_PERSISTENCE_RC=${F_WIFI_PERSISTENCE_RC/net_qube=\"sys-net\"/net_qube=\"$QUBE\"}

install -d -m 0755 /rw/config/rc.local-early.d
dest=/rw/config/rc.local-early.d/wifi-persistence.rc
printf '%s\n' "$F_WIFI_PERSISTENCE_RC" > "$dest.new"
chown root:root "$dest.new"; chmod 0755 "$dest.new"; mv -f "$dest.new" "$dest"
install -d -m 0700 -o root -g root /usr/local/etc/nm-connections

echo "installed $dest (net qube: $QUBE) and /usr/local/etc/nm-connections/"
echo "save a network into it from dom0 after joining it in $QUBE:"
echo "  f='<network name>.nmconnection'"
echo "  qvm-run -u root --pass-io $QUBE \"cat '/etc/NetworkManager/system-connections/\$f'\" |"
echo "    qvm-run -u root --pass-io $(qubesdb-read /name 2>/dev/null || echo '<this dvm>') \"umask 077; cat > '/usr/local/etc/nm-connections/\$f'\""
__END_S_SYS_NET_WIFI__
)
S_SYS_VPN_WIREGUARD=$(cat <<'__END_S_SYS_VPN_WIREGUARD__'
#!/bin/bash
# sys-vpn-wireguard/setup.sh - load WireGuard configs into a disposable VPN qube at boot.
# GENERATED by tools/build.py from the plain files beside it: edit those, then rebuild.
#
# Run as root in the VPN qube's DISPOSABLE TEMPLATE (e.g. sys-vpn-dvm), not in
# the disposable itself. Either, inside the disposable template:
#   sudo bash setup.sh [--qube sys-vpn] [--default wg-xx]
# or from dom0, after copying setup.sh into the disposable template:
#   qvm-run -u root -p sys-vpn-dvm 'bash /home/user/QubesIncoming/<qube>/setup.sh'
#
# Options:
#   --qube NAME      name of the VPN qube that should load the configs (default sys-vpn)
#   --default NAME   config to bring up (file name without .conf); default: random
#
# Installs (re-running replaces the script and keeps your configs):
#   /rw/config/rc.local.d/vpn-autoconnect.rc   0755  imports the configs at boot
#   /usr/local/etc/wg-configs/                 0700  WireGuard .conf files
#
# Needs NetworkManager in the template (qubes-core-agent-network-manager).

set -euo pipefail

QUBE=sys-vpn
DEFAULT=
while [ $# -gt 0 ]; do
    case "$1" in
        --qube) QUBE=${2:?--qube needs a name}; shift 2 ;;
        --default) DEFAULT=${2:?--default needs a name}; shift 2 ;;
        -h|--help) sed -n '2,22p' "$0" 2>/dev/null || true; exit 0 ;;
        *) echo "unknown option: $1" >&2; exit 2 ;;
    esac
done
[[ $QUBE =~ ^[A-Za-z0-9][A-Za-z0-9_-]*$ ]] || { echo "invalid qube name: $QUBE" >&2; exit 2; }
[[ -z $DEFAULT || $DEFAULT =~ ^[A-Za-z0-9_=+.-]{1,15}$ ]] || { echo "invalid config name: $DEFAULT (max 15 characters)" >&2; exit 2; }
[ "$(id -u)" -eq 0 ] || { echo "run as root (see the top of this file)" >&2; exit 1; }
if [ "$(qubesdb-read /qubes-vm-persistence 2>/dev/null || true)" = none ]; then
    echo "this is a disposable: anything installed here is lost at shutdown." >&2
    echo "run it in the disposable template instead (e.g. sys-vpn-dvm)." >&2
    exit 1
fi
command -v nmcli >/dev/null || echo "WARN: nmcli not found: the template needs NetworkManager" >&2

F_VPN_AUTOCONNECT_RC=$(cat <<'__END_F_VPN_AUTOCONNECT_RC__'
#!/bin/bash
# Set up a disposable WireGuard VPN qube at boot.
# Installed by sys-vpn-wireguard/setup.sh (or the all-in-one setup) in the VPN
# qube's disposable template, e.g. sys-vpn-dvm, as
#   /rw/config/rc.local.d/vpn-autoconnect.rc   (executable)
# together with the config folder (owned by root, mode 700):
#   /usr/local/etc/wg-configs
# Add WireGuard configs from dom0 (piped straight through, never shown in dom0):
#   f='<name>.conf'
#   qvm-run --pass-io <source qube> "cat '/home/user/path/to/$f'" |
#     qvm-run -u root --pass-io sys-vpn-dvm "umask 077; cat > '/usr/local/etc/wg-configs/$f'"
# or open a root terminal in the dvm template ('qvm-run -u root sys-vpn-dvm
# xfce4-terminal') and move files there after qvm-copy.
# File names become interface names: max 15 characters.
# The VPN qube's name and default config are set below (setup.sh --qube NAME
# --default NAME sets them for you).

set -euo pipefail
shopt -s nullglob

vpn_qube="sys-vpn"
wg_config_dir="/usr/local/etc/wg-configs"
default_vpn=""   # file name without .conf, e.g. "wg-xx"; blank or invalid = random

files=("$wg_config_dir"/*.conf)
(( ${#files[@]} )) || exit 0

# Fast path: sys-vpn
if [ "$(qubesdb-read /name)" = "$vpn_qube" ]; then
    # Delete stored keys however the script exits
    trap 'rm -f -- "${files[@]}"' EXIT

    # Import each config; skip any that fail
    imported=()
    for f in "${files[@]}"; do
        name="${f##*/}"
        nmcli connection import type wireguard file "$f" && imported+=("${name%.conf}")
    done
    (( ${#imported[@]} )) || exit 1

    # Use default if it imported, otherwise pick one at random
    if [[ -z "$default_vpn" || " ${imported[*]} " != *" $default_vpn "* ]]; then
        default_vpn="${imported[RANDOM % ${#imported[@]}]}"
    fi

    for vpn in "${imported[@]}"; do
        [ "$vpn" = "$default_vpn" ] || nmcli connection down "$vpn" || true
    done

    exit 0
fi

# Safety net: strip stored configs from any other disposable
if [ "$(qubesdb-read /qubes-vm-persistence)" = "none" ]; then
    rm -f -- "${files[@]}"
fi
__END_F_VPN_AUTOCONNECT_RC__
)
F_VPN_AUTOCONNECT_RC=${F_VPN_AUTOCONNECT_RC/vpn_qube=\"sys-vpn\"/vpn_qube=\"$QUBE\"}
F_VPN_AUTOCONNECT_RC=${F_VPN_AUTOCONNECT_RC/default_vpn=\"\"/default_vpn=\"$DEFAULT\"}

install -d -m 0755 /rw/config/rc.local.d
dest=/rw/config/rc.local.d/vpn-autoconnect.rc
printf '%s\n' "$F_VPN_AUTOCONNECT_RC" > "$dest.new"
chown root:root "$dest.new"; chmod 0755 "$dest.new"; mv -f "$dest.new" "$dest"
install -d -m 0700 -o root -g root /usr/local/etc/wg-configs

echo "installed $dest (VPN qube: $QUBE, default: ${DEFAULT:-random}) and /usr/local/etc/wg-configs/"
echo "add a config from dom0 (piped through, never shown in dom0):"
echo "  qvm-run --pass-io <source qube> 'cat ~/wg-xx.conf' |"
echo "    qvm-run -u root --pass-io $(qubesdb-read /name 2>/dev/null || echo '<this dvm>') 'umask 077; cat > /usr/local/etc/wg-configs/wg-xx.conf'"
__END_S_SYS_VPN_WIREGUARD__
)
S_FLATPAK=$(cat <<'__END_S_FLATPAK__'
#!/bin/bash
# flatpak/setup.sh - Flatpak integration for a Qubes TEMPLATE.
# GENERATED by tools/build.py from the plain files beside it: edit those, then rebuild.
#
# Run as root in a template (e.g. fedora-44-minimal):
#   sudo bash setup.sh
#
# Installs:
#   the flatpak package (dnf) and the Flathub remote (system-wide, via the updates proxy)
#   /etc/qubes/post-install.d/05-flatpak-update.sh   0755  upgrades Flatpak apps after
#                                                          each dnf transaction in the template
#   /etc/profile.d/flatpak-proxy.sh                  0644  points shells in the template at
#                                                          the updates proxy
# With minimal templating: also adds 'flatpak' to /etc/minimal-templating/master.dnf,
# so derived templates keep it only where their list does.
#
# Install apps system-wide afterwards, e.g.:
#   sudo env http_proxy=http://127.0.0.1:8082 https_proxy=http://127.0.0.1:8082 \
#     flatpak install --system -y flathub org.signal.Signal

set -euo pipefail

case "${1:-}" in -h|--help) sed -n '2,22p' "$0" 2>/dev/null || true; exit 0 ;; esac
[ "$(id -u)" -eq 0 ] || { echo "run as root: sudo bash setup.sh" >&2; exit 1; }
[ "$(qubesdb-read /qubes-vm-type 2>/dev/null || true)" = TemplateVM ] || {
    echo "run this in a template (TemplateVM), not in an app qube or disposable" >&2; exit 1; }

F_05_FLATPAK_UPDATE_SH=$(cat <<'__END_F_05_FLATPAK_UPDATE_SH__'
#!/bin/sh

# abort if not in a template
if [ "$(qubesdb-read /type 2>/dev/null)" != "TemplateVM" ]; then
    echo "Not a template, skipping flatpak update" >&2
    exit 1
fi

export http_proxy=http://127.0.0.1:8082
export https_proxy=http://127.0.0.1:8082

flatpak upgrade -y --noninteractive
__END_F_05_FLATPAK_UPDATE_SH__
)
F_FLATPAK_PROXY_SH=$(cat <<'__END_F_FLATPAK_PROXY_SH__'
# /etc/profile.d/flatpak-proxy.sh
if [ "$(qubesdb-read /type 2>/dev/null)" = "TemplateVM" ]; then
    export http_proxy=http://127.0.0.1:8082
    export https_proxy=http://127.0.0.1:8082
fi
__END_F_FLATPAK_PROXY_SH__
)
install_file() {   # install_file <content> <path> <mode>
    install -d -m 0755 "$(dirname "$2")"
    printf '%s\n' "$1" > "$2.new"
    chown root:root "$2.new"; chmod "$3" "$2.new"; mv -f "$2.new" "$2"
}

dnf -y install flatpak
http_proxy=http://127.0.0.1:8082 https_proxy=http://127.0.0.1:8082 \
    flatpak remote-add --system --if-not-exists flathub https://dl.flathub.org/repo/flathub.flatpakrepo
install_file "$F_05_FLATPAK_UPDATE_SH"  /etc/qubes/post-install.d/05-flatpak-update.sh 0755
install_file "$F_FLATPAK_PROXY_SH" /etc/profile.d/flatpak-proxy.sh 0644
echo "installed flatpak, the Flathub remote, the update hook and the proxy file"

M=/etc/minimal-templating/master.dnf
if [ -f "$M" ] && ! grep -qx flatpak "$M"; then
    printf '\n# Flatpak (added by flatpak/setup.sh)\nflatpak\n' >> "$M"
    echo "added flatpak to $M (list it in each derived template's .dnf that keeps Flatpak apps)"
fi
__END_S_FLATPAK__
)
# ------------------------------------------------------------------ shared dom0 helpers
# (tools/dom0-lib.sh: the same in every dom0 script built by tools/build.py)
#
# How a qube a module defines is treated when one of that name already exists:
#   wrong kind (e.g. 'files' exists as a disposable)
#       -> kept as <name>-old (or -old-2, ...), never deleted: it may hold data.
#          A fresh one of the right kind is made.
#   right kind, holds nothing of yours (disposable templates, named disposables)
#       -> removed and made again, so it is exactly what the module defines.
#          Files the module lists as yours (e.g. an allow-list) are carried over.
#   right kind, holds your data (app qubes such as 'files') or is a template
#       -> kept; its settings are set to what the module defines.
# Files the modules install inside qubes are overwritten; your own config files
# are kept.

say()  { echo "$*"; }
warn() { echo "   WARN $*"; }
die()  { echo "ERROR: $*" >&2; exit 1; }
ask() {       # ask "question" -> 0 for yes (default no)
    local a
    read -r -p "$1 [y/N] " a
    [[ $a =~ ^[Yy]([Ee][Ss])?$ ]]
}
ask_yes() {   # ask_yes "question" -> 0 for yes (default yes)
    local a
    read -r -p "$1 [Y/n] " a
    ! [[ $a =~ ^[Nn]([Oo])?$ ]]
}
in_vm() { qvm-run --user root --pass-io --no-gui "$1" "$2"; }
push() {   # push <qube> <path> <mode>   (content on stdin; written atomically, owned by root)
    in_vm "$1" "mkdir -p \"\$(dirname '$2')\" && cat > '$2.new' && chown root:root '$2.new' && chmod $3 '$2.new' && mv -f '$2.new' '$2'"
}
exists()  { qvm-check --quiet "$1" 2>/dev/null; }
running() { qvm-check --quiet --running "$1" 2>/dev/null; }
klass()   { qvm-prefs "$1" klass; }
halt() { if exists "$1" && running "$1"; then say "   shutting down $1"; qvm-shutdown --wait "$1"; fi; }
kind() {   # kind <qube> -> TemplateVM | dvm | DispVM | AppVM | StandaloneVM | ...
    local k; k=$(klass "$1")
    if [ "$k" = AppVM ] && [ "$(qvm-prefs "$1" template_for_dispvms)" = True ]; then echo dvm; else echo "$k"; fi
}
describe() { case $1 in dvm) echo "disposable template" ;; DispVM) echo "named disposable" ;;
                        AppVM) echo "app qube" ;; TemplateVM) echo "template" ;; *) echo "$1" ;; esac; }
valid_name() { [[ $1 =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*$ ]] || die "invalid qube name: $1"; }

set_aside() {   # set_aside <qube>: keep it as <qube>-old (clone, then remove the original)
    local q=$1 n=$1-old i=2 err
    while exists "$n"; do n=$q-old-$i; i=$((i + 1)); done
    halt "$q"
    qvm-clone "$q" "$n" >/dev/null
    qvm-prefs "$n" autostart False 2>/dev/null || true
    if ! err=$(qvm-remove --force "$q" 2>&1); then
        die "kept a copy of $q as $n, but couldn't remove $q itself: $err
Something still uses it (as its template, netvm or default disposable). Change that in
Qube Manager, run 'qvm-remove $q', then run this script again."
    fi
    say "   $q was a $(describe "$(kind "$n")"): kept as $n (autostart off; delete it once you don't need it)"
}

remove_qube() {   # remove_qube <qube>: for qubes that hold nothing of yours
    local err
    halt "$1"
    err=$(qvm-remove --force "$1" 2>&1) || die "couldn't remove $1 to make it again: $err
Something still uses it (as its template, netvm or default disposable). Change that in
Qube Manager, then run this script again."
    say "   removed the old $1 (made again below)"
}

make_way() {   # make_way <qube> <kind> recreate|keep
    # Gets an existing <qube> out of the way, or not, by the rules at the top.
    exists "$1" || return 0
    local k; k=$(kind "$1")
    if [ "$k" != "$2" ]; then
        set_aside "$1"
    elif [ "$3" = recreate ]; then
        remove_qube "$1"
    else
        halt "$1"
    fi
}

save_file() {   # save_file <qube> <path>: print that file from an existing AppVM/dvm, if it has it
    exists "$1" && [ "$(klass "$1")" = AppVM ] || return 0
    in_vm "$1" "cat $2" 2>/dev/null || true
    halt "$1" >/dev/null
}

restore_file() {   # restore_file <qube> <path> <content>: put a saved file back (if there was one)
    [ -n "$3" ] || return 0
    printf '%s\n' "$3" | push "$1" "$2" 0644
    say "   kept your $2 in $1"
}

make_template() {   # make_template <template> [packages...]: clone from $BASE if missing, install
    local t=$1; shift
    if exists "$t"; then
        say "   $t: exists, updating"
    else
        qvm-clone "$BASE" "$t" >/dev/null
        qvm-prefs "$t" label black
        say "   $t: cloned from $BASE"
    fi
    if [ $# -gt 0 ]; then in_vm "$t" "dnf -y install $*"; fi
    qvm-shutdown --wait "$t"
}

write_policy() {   # write_policy <path> <line>...   (sudo; replaces the file)
    local p=$1; shift
    printf '%s\n' "$@" | sudo tee "$p" >/dev/null
    sudo chmod 0644 "$p"
    say "   wrote $p"
    local others
    others=$(grep -lF -- "${*: -1}" /etc/qubes/policy.d/*.policy 2>/dev/null | grep -vx "$p" || true)
    [ -z "$others" ] || warn "other policy files have the same line (check them): $others"
}

remove_old_policy() {   # remove_old_policy <path>: a file an earlier version wrote
    if [ -e "$1" ]; then sudo rm -f "$1"; say "   removed $1 (earlier name of the same policy)"; fi
}

set_menu() {   # set_menu <qube> <desktop files...>
    local q=$1; shift
    if qvm-features "$q" menu-items "$*" && qvm-appmenus --update --force "$q" >/dev/null 2>&1; then
        say "   $q: app menu $*"
    else
        warn "couldn't set $q's app menu: add the apps in Qube Settings > Applications"
    fi
}

set_firewall() {   # set_firewall <qube> <rule>...: allow these, drop everything else
    local q=$1 r; shift
    qvm-firewall "$q" reset
    qvm-firewall "$q" del --rule-no 0
    for r in "$@"; do
        # shellcheck disable=SC2086
        qvm-firewall "$q" add action=accept $r
    done
    qvm-firewall "$q" add action=drop
}

run_setup() {   # run_setup <script text> <qube> [args...]: a module's setup.sh, as root (starts the qube)
    local s=$1 q=$2; shift 2
    printf '%s\n' "$s" | in_vm "$q" "cat > /tmp/module-setup.sh && chmod 0700 /tmp/module-setup.sh"
    in_vm "$q" "bash /tmp/module-setup.sh $*"
}

# ---- minimal templating
conf_base() { awk -F'=' '/^[[:space:]]*base[[:space:]]*=/{gsub(/[[:space:]]/,"",$2); print $2; exit}' "$CONF"; }

pause_watcher() {   # pause the rebuild watcher until this script exits (even after an error)
    if systemctl --user is-enabled --quiet "$UNIT" 2>/dev/null; then
        systemctl --user disable --now "$UNIT" 2>/dev/null || true
        trap 'systemctl --user enable --now "$UNIT" && echo "== watcher enabled again"' EXIT
        say "== watcher paused"
    fi
}

add_to_master() {   # add_to_master <why> <packages...>: append the ones master.dnf lacks (base running)
    local why=$1 master p added=""; shift
    master=$(in_vm "$BASE" "cat $D/master.dnf") || die "$BASE has no $D/master.dnf: run setup-all-in-one.sh first"
    for p in "$@"; do
        printf '%s\n' "$master" | sed 's/#.*//' | tr -s '[:space:]' '\n' | grep -qxF -- "$p" || added="$added $p"
    done
    [ -n "$added" ] || return 0
    # shellcheck disable=SC2086
    { printf '%s\n' "$master"; printf '\n# %s\n' "$why"; printf '%s\n' $added; } | push "$BASE" "$D/master.dnf" 0644
    say "   added to master.dnf:$added"
}

write_list() {   # write_list <qube> <why> <packages...>: its whitelist in the base (replaced)
    local q=$1 why=$2; shift 2
    { echo "# $q: $why"; printf '%s\n' "$@"; } | push "$BASE" "$D/$q.dnf" 0644
    say "   wrote $q.dnf: $*"
}

set_section() {   # set_section <template> <dvm> <qube>: replace that section of templates.conf
    local tmp; tmp=$(mktemp)
    # drop the old section's header and settings (comments stay), then append the new one
    awk -v s="[$1]" '
        { h = $0; gsub(/[[:space:]]/, "", h) }
        /^[[:space:]]*\[/ { inside = (h == s); if (inside) next }
        inside && !/^[[:space:]]*#/ { next }
        { print }' "$CONF" > "$tmp"
    sed -i -e :a -e '/^\n*$/{$d;N;ba' -e '}' "$tmp"     # no trailing blank lines
    printf '\n[%s]\n%s\nqube = %s\n' "$1" "dvm =${2:+ $2}" "$3" >> "$tmp"
    cat "$tmp" > "$CONF"; rm -f "$tmp"
    say "   [$1] dvm = ${2:-(blank)}, qube = $3"
}
SYS_NET_WIFI_run() {   # SYS_NET_WIFI_run <qube>: sys-net Wi-Fi persistence
    say "   running sys-net-wifi/setup.sh in $1"
    run_setup "$S_SYS_NET_WIFI" "$1" --qube sys-net || { rc=$?; [ "$rc" -eq 3 ] || die "sys-net-wifi/setup.sh failed in $1 (exit $rc)"; warn "sys-net-wifi: finished with a warning (see above)"; }
}
SYS_VPN_WIREGUARD_run() {   # SYS_VPN_WIREGUARD_run <qube>: sys-vpn WireGuard autoconnect
    say "   running sys-vpn-wireguard/setup.sh in $1"
    run_setup "$S_SYS_VPN_WIREGUARD" "$1" --qube sys-vpn || { rc=$?; [ "$rc" -eq 3 ] || die "sys-vpn-wireguard/setup.sh failed in $1 (exit $rc)"; warn "sys-vpn-wireguard: finished with a warning (see above)"; }
}
FLATPAK_run() {   # FLATPAK_run <qube>: Flatpak integration
    say "   running flatpak/setup.sh in $1"
    run_setup "$S_FLATPAK" "$1"  || { rc=$?; [ "$rc" -eq 3 ] || die "flatpak/setup.sh failed in $1 (exit $rc)"; warn "flatpak: finished with a warning (see above)"; }
}

# ------------------------------------------------------------------ helpers
names() {   # package names from a list: comments and blank lines removed
    printf '%s\n' "$1" | sed 's/#.*//' | tr -s '[:space:]' ' '
}
check_names() {
    local p
    for p in $1; do
        [[ $p =~ ^[A-Za-z0-9][A-Za-z0-9._+-]*$ ]] || { echo "bad package name: $p" >&2; exit 1; }
    done
}

# ------------------------------------------------------------------ 0. questions
echo "Minimal templating setup. All questions first; then it runs on its own."
echo
DO_SYS_NET_WIFI=0
DO_SYS_VPN_WIREGUARD=0
DO_FLATPAK=0
DO_SWITCH=0
ask "1/4  Wi-Fi login persistence for sys-net (installed in sys-net-dvm)?" && DO_SYS_NET_WIFI=1
ask "2/4  WireGuard autoconnect for sys-vpn (installed in sys-vpn-dvm)?" && DO_SYS_VPN_WIREGUARD=1
ask "3/4  Flatpak integration in the base (flatpak, Flathub, update hook, proxy)?" && DO_FLATPAK=1
echo
echo "4/4  Near the end, the switch-over shuts down ALL running qubes, makes every"
echo "     sys- qube a named disposable (app qubes kept as <name>-old), and starts"
echo "     the sys- qubes again. SAVE ALL OPEN FILES IN EVERY QUBE before it gets there."
ask "     Do the switch-over?" && DO_SWITCH=1
echo
echo "Running: sys-net-wifi=$DO_SYS_NET_WIFI sys-vpn-wireguard=$DO_SYS_VPN_WIREGUARD flatpak=$DO_FLATPAK switch-over=$DO_SWITCH"
echo

# ------------------------------------------------------------------ 1. watcher off
echo "== watcher"
if systemctl --user is-active --quiet "$UNIT" 2>/dev/null || \
   systemctl --user is-enabled --quiet "$UNIT" 2>/dev/null; then
    systemctl --user disable --now "$UNIT"
    echo "   stopped for setup (enabled again at the end)"
else
    echo "   not running"
fi

# ------------------------------------------------------------------ 2. dom0 files
echo "== dom0 files"
mkdir -p "$BIN" "$CONF_DIR" "$UNIT_DIR" "$STATE_DIR"
printf '%s\n' "$F_MAIN"   > "$BIN/minimal-templating"
printf '%s\n' "$F_LISTEN" > "$BIN/minimal-templating-listen"
chmod 0755 "$BIN/minimal-templating" "$BIN/minimal-templating-listen"
printf '%s\n' "$F_UNIT"   > "$UNIT_DIR/$UNIT"
printf '%s\n' "$F_CONF"   > "$CONF_DIR/templates.conf.example"
if [ -f "$CONF" ]; then
    echo "   kept your existing templates.conf (default is in templates.conf.example)"
else
    cp "$CONF_DIR/templates.conf.example" "$CONF"
    echo "   wrote default templates.conf"
fi
chmod 0644 "$UNIT_DIR/$UNIT" "$CONF" "$CONF_DIR/templates.conf.example"
systemctl --user daemon-reload
echo "   installed minimal-templating, minimal-templating-listen, service unit"

# ------------------------------------------------------------------ 3. base template
BASE=$(conf_base)
[ -n "$BASE" ] || { echo "no 'base =' in templates.conf" >&2; exit 1; }

echo "== $BASE"
if ! qvm-check --quiet "$BASE" 2>/dev/null; then
    echo "   not found: downloading and installing it (this takes a while)"
    qvm-template install "$BASE"
fi

echo "   dnf upgrade"
in_vm "$BASE" "dnf -y upgrade"

MASTER_VAR=
for kv in "${LISTS[@]}"; do
    if [ "${kv%%:*}" = master.dnf ]; then MASTER_VAR=${kv#*:}; fi
done
[ -n "$MASTER_VAR" ] || { echo "internal error: master.dnf not embedded" >&2; exit 1; }
PKGS=$(names "${!MASTER_VAR}"); check_names "$PKGS"
echo "   installing master.dnf packages: $PKGS"
in_vm "$BASE" "dnf -y install $PKGS"

in_vm "$BASE" "mkdir -p $D && chown root:root $D && chmod 0755 $D"
printf '%s\n' "$F_APPLY" | push "$BASE" "$D/apply" 0755
for kv in "${LISTS[@]}"; do
    name=${kv%%:*}; var=${kv#*:}
    printf '%s\n' "${!var}" | push "$BASE" "$D/$name" 0644
done
echo "   wrote $D/apply and lists: $(for kv in "${LISTS[@]}"; do printf '%s ' "${kv%%:*}"; done)"
if [ "$DO_FLATPAK" -eq 1 ]; then FLATPAK_run "$BASE"; fi

qvm-shutdown --wait "$BASE"
echo "   $BASE shut down, disk saved"

# ------------------------------------------------------------------ 4. build
# Offline: everything keeps running while the templates and dvms are built.
echo "== building derived templates (your qubes keep running)"
if ! "$BIN/minimal-templating"; then
    echo
    echo "Build had failures (see ~/.local/state/minimal-templating/minimal-templating.log)."
    echo "Nothing has been switched over. Fix the lists, then re-run this script."
    exit 1
fi

# ------------------------------------------------------------------ 5. disposable templates
echo "== disposable templates"
# every name on every 'dvm =' line (a shared template lists several)
DVMS=$(awk -F'=' '/^[[:space:]]*dvm[[:space:]]*=/{n=split($2,a,/[[:space:]]+/); for(i=1;i<=n;i++) if(a[i]!="") print a[i]}' "$CONF")
for dvm in $DVMS; do
    qvm-check --quiet "$dvm" 2>/dev/null || { echo "   $dvm: missing, skipped"; continue; }
    in_vm "$dvm" "mkdir -p $RC_DIRS"
    qvm-shutdown --wait "$dvm"
    echo "   $dvm: rc.local.d, rc.local-early.d"
done
if [ "$DO_SYS_NET_WIFI" -eq 1 ]; then
    if exists sys-net-dvm; then SYS_NET_WIFI_run sys-net-dvm; qvm-shutdown --wait sys-net-dvm
    else warn "sys-net-dvm not found: sys-net-wifi skipped"; fi
fi
if [ "$DO_SYS_VPN_WIREGUARD" -eq 1 ]; then
    if exists sys-vpn-dvm; then SYS_VPN_WIREGUARD_run sys-vpn-dvm; qvm-shutdown --wait sys-vpn-dvm
    else warn "sys-vpn-dvm not found: sys-vpn-wireguard skipped"; fi
fi

# ------------------------------------------------------------------ 6. switch-over
if [ "$DO_SWITCH" -eq 1 ]; then
    echo "== switch-over (shutting down all qubes)"
    "$BIN/minimal-templating" --switch --yes || true
else
    echo "== switch-over skipped (run 'minimal-templating --switch' when ready)"
fi

# ------------------------------------------------------------------ watcher on
# Its startup check finds last-update unchanged since the build above, so it
# doesn't rebuild again now; it just waits for the next base update.
echo "== watcher"
systemctl --user enable --now "$UNIT"
echo "   enabled: rebuilds automatically after every update of $BASE"

case ":$PATH:" in *":$HOME/.local/bin:"*) ;; *)
    echo "NOTE ~/.local/bin is not on your PATH; run ~/.local/bin/minimal-templating, or log out and in" ;;
esac

cat <<EOF

Done.
  minimal-templating --status          check every stack
  Qube Manager                         check the sys- qubes; old ones are kept as *-old
  qvm-remove <name>-old                delete each backup once you no longer need it
  systemctl --user disable --now $UNIT turn the automatic rebuild off
EOF
[ "$WARNED" -eq 0 ] || echo "Finished with a warning: see the messages above."
if [ "$DO_SYS_NET_WIFI" -eq 1 ]; then
cat <<EOF

sys-net-wifi:
To save a network after joining it in sys-net, run in dom0 (the file is piped
through, never shown):
  f='<network name>.nmconnection'
  qvm-run -u root --pass-io sys-net "cat '/etc/NetworkManager/system-connections/\$f'" |
    qvm-run -u root --pass-io sys-net-dvm "umask 077; cat > '/usr/local/etc/nm-connections/\$f'"
EOF
fi
if [ "$DO_SYS_VPN_WIREGUARD" -eq 1 ]; then
cat <<EOF

sys-vpn-wireguard:
Add a WireGuard config from dom0 (piped through, never shown in dom0):
  qvm-run --pass-io <source qube> 'cat ~/wg-xx.conf' |
    qvm-run -u root --pass-io sys-vpn-dvm 'umask 077; cat > /usr/local/etc/wg-configs/wg-xx.conf'
EOF
fi
if [ "$DO_FLATPAK" -eq 1 ]; then
cat <<EOF

flatpak:
Install apps system-wide in the template afterwards, e.g.:
  sudo env http_proxy=http://127.0.0.1:8082 https_proxy=http://127.0.0.1:8082 \\
    flatpak install --system -y flathub org.signal.Signal
EOF
fi
